<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;use App\Http\Requests\{ComponentRequest,ComponentFilterRequest};use App\Http\Resources\ComponentResource;use App\Models\Component;use App\Services\ComponentService;
class ComponentController extends Controller {public function __construct(private ComponentService $service){}public function index(ComponentFilterRequest $r){return ComponentResource::collection($this->service->search($r->validated()));}public function show(Component $component){return new ComponentResource($component->load('category'));}public function store(ComponentRequest $r){return (new ComponentResource(Component::create($r->validated())))->response()->setStatusCode(201);}public function update(ComponentRequest $r,Component $component){$component->update($r->validated());return new ComponentResource($component);}public function destroy(Component $component){if($component->configurations()->exists())return response()->json(['message'=>'Комплектующее используется в сборках'],409);$component->delete();return response()->noContent();}}
